<!-- Generated by EldUI from the design file — deterministic export (no AI). -->
<script lang="ts">
import { defineComponent, type PropType } from 'vue'

export default defineComponent({
  name: 'ButtonBreadcrumb',
  props: {
    state: { type: String as PropType<'default' | 'hover' | 'active'>, default: 'default' },
    text: { type: String, default: 'Button text' },
    urlTo: { type: String, default: '' },
  },
  methods: {
    onButtonBreadcrumbClick() {
      { const to = this.urlTo; if (/^[a-z][a-z0-9+.-]*:/i.test(to)) window.open(to, '_blank', 'noopener'); else if (to) this.$router.push(to) }
    },
  },
})
</script>

<template>
  <div
    class="button-breadcrumb"
    :class="['button-breadcrumb--state-' + state]"
    @click="onButtonBreadcrumbClick"
  >
    <p class="button-text">{{ text }}</p>
  </div>
</template>

